basic.fetcher:
(async function (args, reqOptions) {
  const baseUrl = await BeaconBar.executeFunction("reqOptions")();

  const finalUrl = `${baseUrl}GPAdding/Api/widgets/ExternalSlipApi/GetPayPeriod`;


  if (!args?.PayType || !args?.PayYear) {
    throw new Error("PayType and PayYear are required");
  }

  return {
    url: finalUrl,
    method: "POST",
    headers: {
      "x-requested-with": "XMLHttpRequest",
      "Content-Type": "application/json"
    },
    credentials: "include",
    body: JSON.stringify({
      EmpNumber: args?.EmpNumber || "",
      PayType: args?.PayType,
      PayYear: args?.PayYear,
      PaySchId: args?.PaySchId || "",
      PayPeriod: "",
      PayStartDate: "",
      PayEndDate: ""
    })
  };
})

basic.transformer:
(function (data) {
  return data.map(item => ({
    PayGrpCode: item.PayGrpCode,
    PayStartDate: item.PayStartDate,
    PayEndDate: item.PayEndDate,
    PayGrpNum: item.PayType,
    PayPeriod: item.PayPeriod
  }));
})

basic.sourceConstructor:
(function(data, args, reqOptions) {
  return data.map(item => ({
    url: "",
    title: item.PayPeriod,
    subTitle: `Year: ${item.PayYear}`,
    icon: ""
  }));
})

